SELECT 
FROM building_sweep_report

    del_flag = '0'

        AND (report_no LIKE CONCAT('%', #{keyword}, '%')
            OR area_full_name LIKE CONCAT('%', #{keyword}, '%')
            OR detail_address LIKE CONCAT('%', #{keyword}, '%'))


        AND inspection_time >= #{inspectionTimeStart}


        AND inspection_time <= #{inspectionTimeEnd}


        AND review_status = #{reviewStatus}


        AND street_name = #{streetName}


        AND FIND_IN_SET(CAST(#{subjectType} AS CHAR), subject_types) > 0


ORDER BY report_time DESC, id DESC
